package dev.mineagent.runtime.neoforge.client.nativeui;
import com.lowdragmc.lowdraglib2.gui.ui.UIElement;import com.lowdragmc.lowdraglib2.gui.ui.elements.*;import com.lowdragmc.lowdraglib2.gui.holder.ModularUIScreen;import net.minecraft.client.Minecraft;import java.util.*;import java.util.concurrent.*;
/** Drive visible model settings and independently read persisted routing. */
@net.neoforged.fml.common.EventBusSubscriber(modid="mineagent_runtime",value=net.neoforged.api.distmarker.Dist.CLIENT)
public final class ModelSettingsSmoke {
 private static CompletableFuture<Map<String,Object>> result;private static UUID agent;private static int stage,ticks,wait;private static boolean busy;
 public static CompletableFuture<Map<String,Object>> run(UUID id){if(!Boolean.getBoolean("mineagent.skillSmoke"))throw new IllegalStateException("SMOKE_DISABLED");agent=id;result=new CompletableFuture<>();Minecraft.getInstance().execute(()->NativeWorkspaceScreen.openForAgent(id.toString(),"模型设置验证"));return result;}
 private static UIElement root(){var screen=Minecraft.getInstance().screen;return screen instanceof NativeWorkspaceScreen s?s.smokeRoot():screen instanceof AgentProfileScreen p?p.smokeRoot():null;}
 private static UIElement find(UIElement root,String id){if(root==null)return null;if(root.getId().equals(id))return root;for(var c:root.getChildren()){var found=find(c,id);if(found!=null)return found;}return null;}
 private static boolean click(String id){var node=find(root(),id);if(!(node instanceof Button b)||!b.isActive()||b.getSizeHeight()<1)return false;float x=b.getPositionX()+b.getSizeWidth()/2,y=b.getPositionY()+b.getSizeHeight()/2;for(var p=b.getParent();p!=null;p=p.getParent())if(p instanceof ScrollerView scroll){float low=scroll.viewPort.getContentY(),high=low+scroll.viewPort.getContentHeight(),range=scroll.getContainerHeight()-scroll.viewPort.getContentHeight();if(range>0&&(y-b.getSizeHeight()/2<low||y+b.getSizeHeight()/2>high)){scroll.verticalScroller.setNormalizedValue(Math.clamp(scroll.verticalScroller.getNormalizedValue()+(y-(low+high)/2)/range,0,1));return false;}}var screen=(ModularUIScreen)Minecraft.getInstance().screen;screen.modularUI.refreshHoveredElementAtScreen(x,y);var widget=com.lowdragmc.lowdraglib2.gui.ui.ModularUIClientAccess.getWidget(screen.modularUI);var event=new net.minecraft.client.input.MouseButtonEvent(x,y,new net.minecraft.client.input.MouseButtonInfo(0,0));widget.mouseClicked(event,false);widget.mouseReleased(event);return true;}
 private static void screenshot(String name){var mc=Minecraft.getInstance();net.minecraft.client.Screenshot.takeScreenshot(mc.getMainRenderTarget(),image->{try(image){var folder=java.nio.file.Files.createDirectories(mc.gameDirectory.toPath().resolve("model-settings-images"));image.writeToFile(folder.resolve(name+".png"));}catch(Exception error){result.completeExceptionally(error);}});}
 private static void next(){stage++;wait=0;}
 @net.neoforged.bus.api.SubscribeEvent @SuppressWarnings({"unchecked","rawtypes"}) public static void tick(net.neoforged.neoforge.client.event.ClientTickEvent.Post event){if(result==null||result.isDone())return;try{if(ticks%100==0)java.nio.file.Files.writeString(Minecraft.getInstance().gameDirectory.toPath().resolve("model-settings-progress.json"),"{\"stage\":"+stage+",\"ticks\":"+ticks+"}");if(++ticks>1500)throw new IllegalStateException("MODEL_SETTINGS_TIMEOUT_"+stage);if(busy||!NativeWorkspaceConnection.ready())return;var mc=Minecraft.getInstance();if(stage==0&&mc.screen instanceof NativeWorkspaceScreen host){WorkspacePanels.settings(host);next();}
 else if(stage==1){var node=find(root(),"settings-category");if(node instanceof Selector selector&&selector.getCandidates().contains("AI 玩家模型")){selector.setValue("AI 玩家模型",true);next();}}
 else if(stage==2){if(click("settings-ai-model-"+agent))next();}
 else if(stage==3||stage==7){if(stage==7&&find(root(),"agent-model-mode")==null){if(++wait>10)click("agent-tab-model");return;}var node=find(root(),"agent-model-mode");var field=find(root(),"agent-custom-model-id");if(node instanceof Selector selector&&field instanceof TextField input&&!input.getValue().isBlank()){selector.setValue(selector.getCandidates().get(1),true);input.setText(stage==3?"fixture/custom-first":"fixture/custom-second",true);next();}}
 else if(stage==4||stage==8){if(++wait>8&&click("agent-model-save"))next();}
 else if(stage==5||stage==9){busy=true;int expectedStage=stage;WorkspacePanels.request("agent.modelRead",Map.of("agentId",agent.toString())).whenComplete((receipt,error)->{busy=false;if(error!=null){result.completeExceptionally(error);return;}var state=WorkspacePanels.state(receipt);String expected=expectedStage==5?"fixture/custom-first":"fixture/custom-second";if(!state.get("model").getAsString().equals(expected))return;screenshot(expectedStage==5?"settings-per-ai-model":"profile-per-ai-model");if(expectedStage==5)next();else result.complete(Map.of("status","PASS","customIdsSavedThroughBothVisibleEntrypoints",true,"paidModelCalls",0));});}
 else if(stage==6){AgentProfileScreen.open(agent,"模型设置验证");next();}
 }catch(Exception error){result.completeExceptionally(error);}}
 private ModelSettingsSmoke(){}
}
